SELECT mf.movement_id, mf.item_id, mf.item_name, mf.type, mf.quantity_delta, mf.from_location_id, mf.from_location_path, mf.to_location_id, mf.to_location_path, mf.operator_account_id, mf.operator_display_name, mf.reason, mf.business_time FROM reporting_movement_flat mf WHERE mf.household_id = #{householdId} AND mf.business_time BETWEEN #{from} AND #{to} AND mf.item_id = #{itemId}
AND (mf.from_location_id = #{locationId} OR mf.to_location_id = #{locationId})
AND mf.type = #{type} ORDER BY mf.business_time DESC

SELECT
    mf.movement_id, mf.item_id, mf.item_name,
    mf.type, mf.quantity_delta,
    mf.from_location_id, mf.from_location_path,
    mf.to_location_id, mf.to_location_path,
    mf.operator_account_id, mf.operator_display_name,
    mf.reason, mf.reversal_of, mf.business_time, mf.created_at
FROM reporting_movement_flat mf
WHERE mf.household_id = #{householdId}
AND mf.business_time >= #{from}
AND mf.business_time <= #{to}
AND mf.item_id = #{itemId}
AND mf.type = #{type}
AND mf.operator_account_id = #{operatorAccountId}
ORDER BY mf.business_time DESC
